// Pure helpers for the global catalog: normalizing names so different sources
// agree, parsing YouTube Music's auto-generated track descriptions, and typing
// releases. No I/O here, so it's all unit-tested (lib_test.ts).

const QUALIFIERS =
  /\s*[([](?:[^)\]]*\b(?:deluxe|expanded|remaster(?:ed)?|edition|version|anniversary|bonus|explicit|clean|mono|stereo)\b[^)\]]*)[)\]]/gi;
const FEAT = /\s*[([]?\b(?:feat\.?|ft\.?|featuring|with)\s+[^)\]]*[)\]]?/gi;
const VIDEO_NOISE =
  /\s*[([](?:official\s*(?:music\s*)?(?:video|audio|visualizer|lyric(?:s)?\s*video)?|lyrics?|audio|visualizer|hd|hq|4k|explicit|clean)[)\]]/gi;

function fold(s: string): string {
  return s
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")       // accents
    .replace(/[’‘`´]/g, "'")
    .replace(/&/g, " and ")
    .toLowerCase();
}

/** Artist names: "Beyoncé" == "beyonce", "Simon & Garfunkel" == "simon and garfunkel". */
export function normName(s: string): string {
  return fold(s).replace(/^the\s+/, "").replace(/[^a-z0-9]+/g, " ").trim();
}

/** Release titles: ignore deluxe/remastered/edition qualifiers so editions match. */
export function normRelease(s: string): string {
  return fold(s.replace(QUALIFIERS, "").replace(/\s+-\s+(single|ep)$/i, ""))
    .replace(/[^a-z0-9]+/g, " ").trim();
}

/** Track titles: also ignore featured artists and video labels. */
export function normTrack(s: string): string {
  return fold(
    s.replace(VIDEO_NOISE, "").replace(FEAT, "").replace(QUALIFIERS, "")
      .replace(/\s+-\s+(?:\d{4}\s+)?remaster(?:ed)?(?:\s+\d{4})?$/i, ""),
  ).replace(/[^a-z0-9]+/g, " ").trim();
}

/** Strip "Artist - " prefixes and "(Official Video)" labels from a YouTube title. */
export function cleanVideoTitle(title: string, artist: string): string {
  let t = title.replace(VIDEO_NOISE, "").trim();
  const prefix = new RegExp(`^${artist.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*[-–—:|]\\s*`, "i");
  t = t.replace(prefix, "").trim();
  return t || title;
}

export interface TopicTrack {
  title: string;
  artists: string[];
  album: string | null;
  releaseDate: string | null;   // YYYY-MM-DD
}

/**
 * Parse the description YouTube writes for auto-generated ("Art Track") videos:
 *
 *   Provided to YouTube by <Label>
 *
 *   <Title> · <Artist> · <Artist>
 *
 *   <Album>
 *
 *   ℗ 2018 <Label>
 *
 *   Released on: 2018-06-29
 *   ...
 *   Auto-generated by YouTube.
 */
export function parseTopicDescription(description: string | null | undefined): TopicTrack | null {
  if (!description || !/provided to youtube by/i.test(description)) return null;
  const blocks = description.split(/\r?\n\s*\r?\n/).map((b) => b.trim()).filter(Boolean);
  const i = blocks.findIndex((b) => b.includes(" · "));
  if (i < 0) return null;
  const [title, ...artists] = blocks[i].split("\n")[0].split(" · ").map((x) => x.trim());
  const next = blocks[i + 1]?.split("\n")[0]?.trim() ?? null;
  const album = next && !/^(℗|©|released on:|auto-generated|composer|lyricist|producer)/i.test(next) ? next : null;
  const date = description.match(/Released on:\s*(\d{4}-\d{2}-\d{2})/i)?.[1] ?? null;
  if (!title) return null;
  return { title, artists, album, releaseDate: date };
}

export type ReleaseType = "album" | "single" | "ep" | "compilation" | "live" | "other";

/** MusicBrainz release-group primary/secondary types → our release type. */
export function releaseTypeFromMB(primary?: string | null, secondary: string[] = []): ReleaseType {
  const sec = secondary.map((s) => s.toLowerCase());
  if (sec.includes("compilation")) return "compilation";
  if (sec.includes("live")) return "live";
  switch ((primary ?? "").toLowerCase()) {
    case "album": return "album";
    case "single": return "single";
    case "ep": return "ep";
    default: return "other";
  }
}

/** Release type for a release only known from YouTube, by track count. */
export function releaseTypeFromCount(tracks: number): ReleaseType {
  if (tracks <= 3) return "single";
  if (tracks <= 6) return "ep";
  return "album";
}

/** ISO-8601 duration ("PT3M21S") → seconds. */
export function isoDurationToSeconds(iso: string | null | undefined): number | null {
  const m = iso?.match(/^P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/);
  if (!m) return null;
  const [, d, h, mi, s] = m.map((x) => Number(x ?? 0));
  return d * 86400 + h * 3600 + mi * 60 + s;
}

export interface MBArtistHit {
  id: string;
  name: string;
  score?: number;
  country?: string;
  type?: string;
  disambiguation?: string;
  tags?: Array<{ name: string; count: number }>;
  aliases?: Array<{ name: string }>;
}

/** Pick the MusicBrainz artist a name refers to: exact (or alias) match first, then a very high score. */
export function pickMBArtist(hits: MBArtistHit[], name: string): MBArtistHit | null {
  const want = normName(name);
  const exact = hits.filter((h) =>
    normName(h.name) === want || (h.aliases ?? []).some((a) => normName(a.name) === want)
  );
  const pool = exact.length ? exact : hits.filter((h) => (h.score ?? 0) >= 95);
  // Among exact matches, MusicBrainz score reflects popularity/relevance.
  return pool.sort((a, b) => (b.score ?? 0) - (a.score ?? 0))[0] ?? null;
}

/** Is this YouTube channel the artist's auto-generated "<Artist> - Topic" channel? */
export function isTopicChannelFor(channelTitle: string, artist: string): boolean {
  const m = channelTitle.match(/^(.*)\s+-\s+Topic$/i);
  return !!m && normName(m[1]) === normName(artist);
}

/** Best playable match for a song among candidate videos (title match, then most viewed). */
export function bestVideoForTitle<T extends { norm_title: string; view_count?: number | null }>(
  candidates: T[],
  title: string,
): T | null {
  const want = normTrack(title);
  const hits = candidates.filter((c) => c.norm_title === want);
  return hits.sort((a, b) => (b.view_count ?? 0) - (a.view_count ?? 0))[0] ?? null;
}
